<?php
declare(strict_types=1);require_once __DIR__.'/../src/db.php';require_once __DIR__.'/../src/auth.php';require_once __DIR__.'/../src/ui.php';require_teacher_or_admin();$pdo=db();$levels=['PRE-A1','A1','A2','B1','B2','C1','C2'];$level=$_GET['level']??'A1';if(!in_array($level,$levels,true))$level='A1';$stmt=$pdo->prepare("SELECT * FROM curriculum_modules WHERE active=true AND level=:level ORDER BY module_order,title");$stmt->execute(['level'=>$level]);$modules=$stmt->fetchAll();
$pageTitle='Currículo';$pageSubtitle='Módulos, objetivos e temas por nível CEFR.';require __DIR__.'/../templates/header.php';?>
<section class="panel"><div class="panel-head"><div><h2>Trilha <?=e($level)?></h2><p><?=count($modules)?> módulo(s) ativo(s) neste nível.</p></div></div><div class="filter-row"><?php foreach($levels as $item):?><a class="btn <?=$level===$item?'btn-primary':'btn-secondary'?> btn-sm" href="/curriculum.php?level=<?=e($item)?>"><?=e($item)?></a><?php endforeach;?></div><?php if(!$modules):?><div class="empty-state"><div class="empty-state-icon"><?=ui_icon('curriculum')?></div><h3>Sem módulos para <?=e($level)?></h3><p>Cadastre conteúdos curriculares para este nível.</p></div><?php else:?><div class="grid-3"><?php foreach($modules as $module):$objectives=ui_json_array($module['objectives']??[]);$grammar=ui_json_array($module['grammar_topics']??[]);$vocabulary=ui_json_array($module['vocabulary_topics']??[]);?><article class="card"><div class="list-row"><span class="badge <?=e(ui_level_class($module['level']))?>"><?=e($module['level'])?></span><span class="label">Módulo <?= (int)$module['module_order']?></span></div><h3 style="font-size:17px;margin:15px 0 7px"><?=e($module['title'])?></h3><p class="muted" style="line-height:1.55"><?=e($module['description']??'')?></p><?php if($objectives):?><h3>Objetivos</h3><?php foreach(array_slice($objectives,0,4) as $item):?><div class="list-card"><p style="margin:0"><?=e($item)?></p></div><?php endforeach;?><?php endif;?><div class="list-meta"><?php foreach(array_slice(array_merge($grammar,$vocabulary),0,6) as $item):?><span class="badge neutral"><?=e($item)?></span><?php endforeach;?></div></article><?php endforeach;?></div><?php endif;?></section>
<?php require __DIR__.'/../templates/footer.php';?>
